table inet syswarden_table {
	chain input_frontline {
		type filter hook input priority filter - 10; policy accept;
		ct state established,related accept
	}

	chain input_backend {
		type filter hook input priority filter + 10; policy drop;
		ct state invalid drop
		tcp flags & (fin | syn | rst | ack) != syn ct state new drop
		ct state established,related accept
		iifname "lo" accept
		ip protocol icmp accept
		meta l4proto ipv6-icmp accept
		tcp dport 22222 accept
		limit rate 2/second burst 5 packets log prefix "[SysWarden-BLOCK] [Catch-All] "
		drop
	}
}
table netdev syswarden_hw_drop {
	set syswarden_blacklist {
		type ipv4_addr
		flags interval
		auto-merge
		elements = { 192.0.2.0/24, 198.51.100.3-198.51.100.5 }
	}

	set syswarden_whitelist {
		type ipv4_addr
		flags interval
		auto-merge
	}

	set syswarden_whitelist6 {
		type ipv6_addr
		flags interval
		auto-merge
	}

	chain ingress_frontline {
		type filter hook ingress device "swv0" priority -500; policy accept;
		ip saddr @syswarden_whitelist accept
		ip6 saddr @syswarden_whitelist6 accept
		ip protocol tcp tcp flags ! fin,syn,rst,psh,ack,urg counter packets 0 bytes 0 drop
		ip protocol tcp tcp flags & (fin | syn | rst | psh | ack | urg) == fin | syn | rst | psh | ack | urg counter packets 0 bytes 0 drop
		ip protocol tcp tcp flags & (fin | syn) == fin | syn counter packets 0 bytes 0 drop
		ip protocol tcp tcp flags & (syn | rst) == syn | rst counter packets 0 bytes 0 drop
		ip saddr @syswarden_blacklist limit rate 2/second burst 5 packets log prefix "[SysWarden-BLOCK] "
		ip saddr @syswarden_blacklist drop
	}
}

